    var target = "127.0.0.1";
    var openPorts = ["135", "445"];

    // Define a function to analyze the scan data
    function handleScanData(data) {
      if (data["target"] === target && data["openPorts"].every(port => port === openPorts[0])) {
        alert("Anomaly detected: The target address is " + target);
      }
    }

